/// <summary>
/// Bug 332315: CB201- "Preview customers" for OR attribute functionality
/// </summary>
[ExtensionOf(classStr(GUPPricingObjectQueryBuilder))]
final class METGUPPricingObjectQueryBuilder_Extension
{
    private boolean isORRule;
    private RecId   pricingRuleCopyRecId;

}

Method.Source:
/// <summary>
/// Constructs a GUPPricingObjectQueryBuilder from a pricing rule copy.
/// </summary>
/// <param name = "_pricingRuleCopy">The pricing rule copy record.</param>
/// <param name = "_modifiedRuleConditionId">The modified rule condition ID.</param>
/// <param name = "_modifiedRuleConditionValue">The modified rule condition value.</param>
/// <param name = "_keepProductRoot">Flag to keep the product root.</param>
/// <returns><c>GUPPricingObjectQueryBuilder</c></returns>
public static GUPPricingObjectQueryBuilder constructFromPricingRuleCopy(
    GUPPricingRuleCopy  _pricingRuleCopy,
    RefRecId        _modifiedRuleConditionId,
    anytype         _modifiedRuleConditionValue,
    boolean         _keepProductRoot)
{
    GUPPricingObjectQueryBuilder builder = next constructFromPricingRuleCopy(_pricingRuleCopy, _modifiedRuleConditionId, _modifiedRuleConditionValue, _keepProductRoot);

    // check this rule has OR relations
    GUPPricingRuleConditionCopy ruleCondCopy;

    // Bug 332315: CB201- "Preview customers" for OR attribute functionality
    // only for header customer attributes
    // need to exclude vendor rebates
    if (_pricingRuleCopy.getSourceLevel() == GUPPricingAttributeSourceLevel::Header
    && TAMRebateParameters::find().METUseOrAttributes)
    {
        select firstonly RecId from ruleCondCopy
            where ruleCondCopy.RuleId == _pricingRuleCopy.RecId
            && ruleCondCopy.METisOR == NoYes::Yes;

        if (ruleCondCopy)
        {
            builder.isORRule = true;
            builder.pricingRuleCopyRecId = _pricingRuleCopy.RecId;
        }
    }

    return builder;
}

/// <summary>
/// Override the query to handle OR attributes
/// </summary>
/// <returns><c>Query</c></returns>
public Query build()
{
    Query query = next build();

    // if isORRule build the query with OR instead of AND
    if (this.isORRule)
    {
        METTAMRebateQueryBuilderORAttributes orAttributes;

        Query queryCustTable = new Query();
        QueryBuildDataSource orRootDS = queryCustTable.addDataSource(tableNum(CustTable), 'RootCustTable');

        orAttributes = METTAMRebateQueryBuilderORAttributes::constructPreview(HeaderLines_IT::Header, queryCustTable, this.pricingRuleCopyRecId);
        query = orAttributes.run();   
    }

    return query;
}
